#include "exercise.h"
#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <ctype.h>
#include <math.h>
void tree_free(tree_node*r){if(!r)return;for(size_t i=0;i<r->count;i++)tree_free(r->children[i]);free(r->children);free(r);}bool build_tree(const record*r,size_t n,tree_node**root){*root=NULL;if(!n)return true;tree_node**nodes=(tree_node**)calloc(n,sizeof(tree_node*));unsigned*p=(unsigned*)calloc(n,sizeof(unsigned));bool ok=true;for(size_t i=0;i<n;i++){if(r[i].id>=n||nodes[r[i].id]||(r[i].id==0?r[i].parent!=0:r[i].parent>=r[i].id)){ok=false;break;}nodes[r[i].id]=(tree_node*)calloc(1,sizeof(tree_node));nodes[r[i].id]->id=r[i].id;p[r[i].id]=r[i].parent;}if(ok)for(size_t i=0;i<n;i++)if(!nodes[i])ok=false;if(!ok){for(size_t i=0;i<n;i++)free(nodes[i]);free(nodes);free(p);return false;}for(size_t i=1;i<n;i++){tree_node*a=nodes[p[i]];a->children=(tree_node**)realloc(a->children,(a->count+1)*sizeof(tree_node*));a->children[a->count++]=nodes[i];}*root=nodes[0];free(nodes);free(p);return true;}

